import Foundation
import SwiftUI

/// States of a cloud agent background helper task.
/// The four required states: running, waiting for your OK, done, stopped.
enum HelperTaskState: String, CaseIterable, Identifiable, Codable {
    case running = "running"
    case waitingForApproval = "waiting for your OK"
    case done = "done"
    case stopped = "stopped"

    var id: String { rawValue }

    var displayTitle: String {
        switch self {
        case .running: "Running"
        case .waitingForApproval: "Waiting for your OK"
        case .done: "Done"
        case .stopped: "Stopped"
        }
    }

    var iconName: String {
        switch self {
        case .running: "arrow.triangle.2.circlepath"
        case .waitingForApproval: "exclamationmark.triangle.fill"
        case .done: "checkmark.circle.fill"
        case .stopped: "stop.circle.fill"
        }
    }
}

/// Alert actions for write/reschedule confirmations.
/// Every write needs a confirmation in the app, and the family stays in the loop.
struct HelperAlertAction: Equatable, Codable {
    var confirmTitle: String
    var cancelTitle: String
    var promptQuestion: String
    var confirmedMessage: String
    var cancelledMessage: String
}

/// A background task running in Google's cloud on behalf of the user.
/// Demo stand-in: cloud agent tasks fixture.
struct HelperTask: Identifiable, Equatable, Codable {
    var id: String
    var title: String
    var subtitle: String
    var detail: String
    var state: HelperTaskState
    var categoryIcon: String
    var agentBadge: String
    var familyStatus: String?
    var alertAction: HelperAlertAction?
    var timestamp: String
}

import Foundation
import Observation
import SwiftUI

// Demo stand-in: cloud agent tasks fixture store
@MainActor
@Observable
final class DashboardStore {
    var tasks: [HelperTask]
    var taskToStop: HelperTask?
    var showingStopConfirmation = false
    var bannerMessage: String?

    init(tasks: [HelperTask] = DashboardFixtures.tasks) {
        self.tasks = tasks
    }

    var waitingTasks: [HelperTask] {
        tasks.filter { $0.state == .waitingForApproval }
    }

    var runningTasks: [HelperTask] {
        tasks.filter { $0.state == .running }
    }

    var doneTasks: [HelperTask] {
        tasks.filter { $0.state == .done }
    }

    var stoppedTasks: [HelperTask] {
        tasks.filter { $0.state == .stopped }
    }

    var activeCount: Int {
        tasks.filter { $0.state == .running || $0.state == .waitingForApproval }.count
    }

    // MARK: - Stop flow (asks for confirmation)

    func requestStop(task: HelperTask) {
        taskToStop = task
        showingStopConfirmation = true
    }

    func confirmStop() {
        guard let task = taskToStop else { return }
        if let index = tasks.firstIndex(where: { $0.id == task.id }) {
            tasks[index].state = .stopped
            showBanner("Stopped helper: \(task.title)")
        }
        taskToStop = nil
        showingStopConfirmation = false
    }

    func cancelStop() {
        taskToStop = nil
        showingStopConfirmation = false
    }

    // MARK: - Alert card confirmations

    func confirmAlert(task: HelperTask) {
        guard let index = tasks.firstIndex(where: { $0.id == task.id }) else { return }
        let message = task.alertAction?.confirmedMessage ?? "Updated train connection."
        tasks[index].title = "Riding 17:33 IC 5 to Zurich"
        tasks[index].detail = message
        tasks[index].state = .running
        tasks[index].alertAction = nil
        showBanner(message)
    }

    func cancelAlert(task: HelperTask) {
        guard let index = tasks.firstIndex(where: { $0.id == task.id }) else { return }
        let message = task.alertAction?.cancelledMessage ?? "Kept original train."
        tasks[index].title = "Watching original 17:31 IC 8 train"
        tasks[index].detail = message
        tasks[index].state = .running
        tasks[index].alertAction = nil
        showBanner(message)
    }

    func resetToFixtures() {
        tasks = DashboardFixtures.tasks
        showBanner("Reset helpers to demo state")
    }

    private func showBanner(_ message: String) {
        withAnimation(.spring(duration: Theme.Motion.base)) {
            bannerMessage = message
        }
        Task {
            try? await Task.sleep(for: .seconds(3))
            withAnimation(.easeOut(duration: Theme.Motion.fast)) {
                if self.bannerMessage == message {
                    self.bannerMessage = nil
                }
            }
        }
    }
}

import SwiftUI

/// Renders a single cloud agent helper task card.
/// Follows Theme.swift tokens: dark glass, large type, buttons at least 60pt, no text under 17pt.
struct DashboardCardView: View {
    let task: HelperTask
    let onStop: (HelperTask) -> Void
    let onConfirmAlert: (HelperTask) -> Void
    let onCancelAlert: (HelperTask) -> Void

    @Environment(\.typeScale) private var type

    var body: some View {
        if task.state == .waitingForApproval {
            alertCard
        } else {
            standardCard
        }
    }

    // MARK: - Alert Card (Waiting for your OK)

    private var alertCard: some View {
        VStack(alignment: .leading, spacing: 16) {
            // Header badge
            HStack(spacing: 8) {
                Image(systemName: "exclamationmark.triangle.fill")
                    .font(.system(size: 18, weight: .bold))
                    .foregroundStyle(Theme.warnText)
                Text("Waiting for your OK")
                    .font(.system(size: 17, weight: .bold))
                    .foregroundStyle(Theme.warnText)
                Spacer()
                Text(task.timestamp)
                    .font(type.meta)
                    .foregroundStyle(Theme.textMuted)
            }
            .padding(.bottom, 2)

            // Alert Title & Question
            Text(task.title)
                .font(type.bodyStrong)
                .foregroundStyle(Theme.textPrimary)
                .fixedSize(horizontal: false, vertical: true)

            // Detail
            Text(task.detail)
                .font(type.body)
                .foregroundStyle(Theme.textSecondary)
                .fixedSize(horizontal: false, vertical: true)

            // Family in the loop indicator
            if let family = task.familyStatus {
                HStack(spacing: 8) {
                    Image(systemName: "heart.fill")
                        .font(.system(size: 17, weight: .semibold))
                        .foregroundStyle(Theme.accentText)
                    Text(family)
                        .font(type.meta)
                        .foregroundStyle(Theme.accentText)
                }
                .padding(.vertical, 2)
            }

            // Confirm & Cancel action buttons (each at least 60pt tall)
            HStack(spacing: 12) {
                if let action = task.alertAction {
                    Button {
                        onCancelAlert(task)
                    } label: {
                        Text(action.cancelTitle)
                            .font(type.button)
                    }
                    .buttonStyle(DashboardButtonStyle(kind: .secondary))

                    Button {
                        onConfirmAlert(task)
                    } label: {
                        Text(action.confirmTitle)
                            .font(type.button)
                    }
                    .buttonStyle(DashboardButtonStyle(kind: .primary))
                }
            }
            .padding(.top, 4)

            // Optional Stop Helper button
            Button {
                onStop(task)
            } label: {
                Label("Stop Helper", systemImage: "stop.circle")
                    .font(type.meta)
            }
            .buttonStyle(DashboardButtonStyle(kind: .dangerOutline))
        }
        .padding(20)
        .glassSurface(.panel, cornerRadius: Theme.Radius.xl)
        .overlay(
            RoundedRectangle(cornerRadius: Theme.Radius.xl, style: .continuous)
                .strokeBorder(Theme.warnSoft.opacity(0.8), lineWidth: 1.5)
        )
    }

    // MARK: - Standard Helper Card (Running, Done, Stopped)

    private var standardCard: some View {
        VStack(alignment: .leading, spacing: 14) {
            // Header: Category icon, Agent badge, Status badge
            HStack(alignment: .center, spacing: 10) {
                Image(systemName: task.categoryIcon)
                    .font(.system(size: 18, weight: .bold))
                    .foregroundStyle(Theme.accentText)
                    .frame(width: 38, height: 38)
                    .background(Circle().fill(Theme.accentSoft))

                VStack(alignment: .leading, spacing: 2) {
                    Text(task.agentBadge)
                        .font(type.meta)
                        .foregroundStyle(Theme.textSecondary)
                    Text(task.subtitle)
                        .font(type.meta)
                        .foregroundStyle(Theme.textMuted)
                }

                Spacer()

                StatusBadgeView(state: task.state)
            }

            // Title
            Text(task.title)
                .font(type.bodyStrong)
                .foregroundStyle(Theme.textPrimary)
                .fixedSize(horizontal: false, vertical: true)

            // Detail
            Text(task.detail)
                .font(type.body)
                .foregroundStyle(Theme.textSecondary)
                .fixedSize(horizontal: false, vertical: true)

            // Family loop status
            if let family = task.familyStatus {
                HStack(spacing: 8) {
                    Image(systemName: "person.2.fill")
                        .font(.system(size: 17, weight: .semibold))
                        .foregroundStyle(Theme.accentText)
                    Text(family)
                        .font(type.meta)
                        .foregroundStyle(Theme.accentText)
                }
            }

            // Bottom row: Timestamp & Stop Button
            HStack(alignment: .center, spacing: 12) {
                Label(task.timestamp, systemImage: "clock")
                    .font(type.meta)
                    .foregroundStyle(Theme.textMuted)

                Spacer()
            }

            // Stop button: present on running tasks, asks for confirmation
            if task.state == .running {
                Button {
                    onStop(task)
                } label: {
                    Label("Stop Helper", systemImage: "stop.circle")
                        .font(type.button)
                }
                .buttonStyle(DashboardButtonStyle(kind: .dangerOutline))
                .padding(.top, 4)
            } else if task.state == .stopped {
                HStack(spacing: 8) {
                    Image(systemName: "pause.circle.fill")
                        .font(.system(size: 18, weight: .semibold))
                        .foregroundStyle(Theme.dangerText)
                    Text("This helper has been stopped.")
                        .font(type.meta)
                        .foregroundStyle(Theme.dangerText)
                }
                .padding(.top, 4)
            } else if task.state == .done {
                HStack(spacing: 8) {
                    Image(systemName: "checkmark.circle.fill")
                        .font(.system(size: 18, weight: .semibold))
                        .foregroundStyle(Theme.successText)
                    Text("Task completed successfully.")
                        .font(type.meta)
                        .foregroundStyle(Theme.successText)
                }
                .padding(.top, 4)
            }
        }
        .padding(18)
        .glassSurface(.panel, cornerRadius: Theme.Radius.xl)
