struct StatusBadgeView: View {
    let state: HelperTaskState
    @Environment(\.typeScale) private var type

    var body: some View {
        HStack(spacing: 6) {
            Image(systemName: state.iconName)
                .font(.system(size: 17, weight: .semibold))
            Text(state.displayTitle)
                .font(.system(size: 17, weight: .semibold))
        }
        .foregroundStyle(textColor)
        .padding(.horizontal, 12)
        .padding(.vertical, 8)
        .background(
            RoundedRectangle(cornerRadius: Theme.Radius.md, style: .continuous)
                .fill(backgroundColor)
        )
        .overlay(
            RoundedRectangle(cornerRadius: Theme.Radius.md, style: .continuous)
                .strokeBorder(borderColor, lineWidth: 1)
        )
    }

    private var textColor: Color {
        switch state {
        case .running: Theme.successText
        case .waitingForApproval: Theme.warnText
        case .done: Theme.accentText
        case .stopped: Theme.dangerText
        }
    }

    private var backgroundColor: Color {
        switch state {
        case .running: Theme.successSoft
        case .waitingForApproval: Theme.warnSoft
        case .done: Theme.accentSoft
        case .stopped: Theme.dangerSoft
        }
    }

    private var borderColor: Color {
        switch state {
        case .running: Theme.successText.opacity(0.3)
        case .waitingForApproval: Theme.warnText.opacity(0.4)
        case .done: Theme.accentBorder
        case .stopped: Theme.dangerText.opacity(0.3)
        }
    }
}

// MARK: - Dashboard Button Style (Guaranteed >= 60pt height)

struct DashboardButtonStyle: ButtonStyle {
    enum Kind {
        case primary
        case secondary
        case dangerOutline
    }

    let kind: Kind
    @Environment(\.isEnabled) private var isEnabled
    @Environment(\.typeScale) private var type

    var bodyHeight: CGFloat {
        max(60, type.control)
    }

    func makeBody(configuration: Configuration) -> some View {
        let shape = RoundedRectangle(cornerRadius: Theme.Radius.lg, style: .continuous)
        configuration.label
            .font(type.button)
            .foregroundStyle(foregroundColor)
            .frame(maxWidth: .infinity, minHeight: bodyHeight)
            .background(backgroundView(shape: shape))
            .overlay(overlayView(shape: shape))
            .shadow(color: kind == .primary && isEnabled ? Theme.accentStrong.opacity(0.35) : .clear, radius: 8, y: 4)
            .opacity(isEnabled ? (configuration.isPressed ? 0.82 : 1) : 0.4)
            .scaleEffect(configuration.isPressed ? 0.98 : 1)
            .animation(.easeOut(duration: Theme.Motion.fast), value: configuration.isPressed)
    }

    private var foregroundColor: Color {
        switch kind {
        case .primary:
            return Color.white
        case .secondary:
            return Theme.textPrimary
        case .dangerOutline:
            return Theme.dangerText
        }
    }

    @ViewBuilder
    private func backgroundView(shape: some Shape) -> some View {
        switch kind {
        case .primary:
            shape.fill(Theme.accent)
        case .secondary:
            shape.fill(Theme.surfaceControl)
        case .dangerOutline:
            shape.fill(Theme.dangerSoft)
        }
    }

    @ViewBuilder
    private func overlayView(shape: some Shape) -> some View {
        switch kind {
        case .primary:
            EmptyView()
        case .secondary:
            shape.strokeBorder(Theme.borderInput, lineWidth: 1)
        case .dangerOutline:
            shape.strokeBorder(Theme.dangerText.opacity(0.35), lineWidth: 1)
        }
    }
}

import SwiftUI

/// Dashboard screen: 'What my helpers are doing'.
/// Lists the cloud agent tasks running in the background.
/// Follows Theme.swift tokens: dark glass, large type, buttons at least 60pt, no text under 17pt, light and dark.
struct DashboardView: View {
    @State private var store = DashboardStore()
    @State private var selectedFilter: FilterOption = .all
    @Environment(\.dismiss) private var dismiss
    @Environment(\.typeScale) private var type

    enum FilterOption: String, CaseIterable, Identifiable {
        case all = "All"
        case waiting = "Needs OK"
        case running = "Running"
        case completed = "Done"

        var id: String { rawValue }
    }

    var filteredTasks: [HelperTask] {
        switch selectedFilter {
        case .all:
            return store.tasks
        case .waiting:
            return store.waitingTasks
        case .running:
            return store.runningTasks
        case .completed:
            return store.tasks.filter { $0.state == .done || $0.state == .stopped }
        }
    }

    var body: some View {
        VStack(spacing: 0) {
            topNavigation

            ScrollView {
                VStack(alignment: .leading, spacing: 20) {
                    headerIntro

                    if let banner = store.bannerMessage {
                        feedbackBanner(banner)
                    }

                    filterRow

                    tasksList
                }
                .padding(.horizontal, 20)
                .padding(.top, 12)
                .padding(.bottom, 24)
            }
            .scrollIndicators(.hidden)

            bottomBar
        }
        .background(AppBackground())
        .confirmationDialog(
            "Stop this helper?",
            isPresented: $store.showingStopConfirmation,
            titleVisibility: .visible,
            presenting: store.taskToStop
        ) { task in
            Button("Stop Helper", role: .destructive) {
                store.confirmStop()
            }
            Button("Keep Running", role: .cancel) {
                store.cancelStop()
            }
        } message: { task in
            Text("Are you sure you want to stop “\(task.title)”? Background monitoring and alerts for this task will end.")
        }
    }

    // MARK: - Top Navigation

    private var topNavigation: some View {
        HStack {
            Text("What my helpers are doing")
                .font(type.answer)
                .tracking(type.answerTracking)
                .foregroundStyle(Theme.textPrimary)
                .lineLimit(1)
                .minimumScaleFactor(0.85)

            Spacer()

            Button {
                dismiss()
            } label: {
                Image(systemName: "xmark")
                    .font(.system(size: 18, weight: .bold))
                    .foregroundStyle(Theme.textPrimary)
                    .frame(width: 48, height: 48)
                    .glassSurface(.flat, cornerRadius: 24)
            }
            .accessibilityLabel("Close")
        }
        .padding(.horizontal, 20)
        .padding(.top, 20)
        .padding(.bottom, 8)
    }

    // MARK: - Header Intro

    private var headerIntro: some View {
        VStack(alignment: .leading, spacing: 10) {
            Text("Cloud agents in Google's cloud work in the background for you. Every write needs your confirmation, and your family stays in the loop.")
                .font(type.body)
                .foregroundStyle(Theme.textSecondary)
                .fixedSize(horizontal: false, vertical: true)

            HStack(spacing: 12) {
                HStack(spacing: 6) {
                    Circle()
                        .fill(Theme.successText)
                        .frame(width: 10, height: 10)
                    Text("\(store.activeCount) active helpers")
                        .font(type.meta)
                        .foregroundStyle(Theme.textPrimary)
                }

                Text("·")
                    .font(type.meta)
                    .foregroundStyle(Theme.textMuted)

                HStack(spacing: 6) {
                    Image(systemName: "shield.checkmark.fill")
                        .font(.system(size: 17))
                        .foregroundStyle(Theme.accentText)
                    Text("Human in the loop")
                        .font(type.meta)
                        .foregroundStyle(Theme.accentText)
                }
            }
        }
        .padding(16)
        .glassSurface(.panel, cornerRadius: Theme.Radius.lg)
    }

    // MARK: - Filter Row

    private var filterRow: some View {
        ScrollView(.horizontal, showsIndicators: false) {
            HStack(spacing: 8) {
                ForEach(FilterOption.allCases) { option in
                    let isSelected = selectedFilter == option
                    Button {
                        selectedFilter = option
                    } label: {
                        Text(option.rawValue)
                            .font(.system(size: 17, weight: .semibold))
                            .foregroundStyle(isSelected ? Theme.textPrimary : Theme.textSecondary)
                            .padding(.horizontal, 16)
                            .frame(minHeight: max(48, type.control - 8))
                            .background(
                                RoundedRectangle(cornerRadius: Theme.Radius.lg, style: .continuous)
                                    .fill(isSelected ? Theme.accent : Theme.surfaceControl)
                            )
                            .overlay(
                                RoundedRectangle(cornerRadius: Theme.Radius.lg, style: .continuous)
                                    .strokeBorder(isSelected ? Theme.accentBorder : Theme.borderSubtle, lineWidth: 1)
                            )
                    }
                    .accessibilityAddTraits(isSelected ? .isSelected : [])
                }
            }
        }
    }

    // MARK: - Tasks List

    private var tasksList: some View {
        VStack(spacing: 16) {
            if filteredTasks.isEmpty {
                VStack(spacing: 12) {
                    Image(systemName: "tray")
                        .font(.system(size: 36, weight: .light))
                        .foregroundStyle(Theme.textMuted)
                    Text("No helpers in this category.")
                        .font(type.body)
                        .foregroundStyle(Theme.textMuted)
                }
                .frame(maxWidth: .infinity)
                .padding(.vertical, 40)
            } else {
                ForEach(filteredTasks) { task in
                    DashboardCardView(
                        task: task,
                        onStop: { store.requestStop(task: $0) },
                        onConfirmAlert: { store.confirmAlert(task: $0) },
                        onCancelAlert: { store.cancelAlert(task: $0) }
                    )
                    .transition(.opacity.combined(with: .scale(scale: 0.98)))
                }
            }
        }
        .animation(.spring(duration: Theme.Motion.panel), value: filteredTasks.map { $0.id + $0.state.rawValue })
    }

    // MARK: - Feedback Banner

    private func feedbackBanner(_ message: String) -> some View {
        HStack(spacing: 10) {
            Image(systemName: "checkmark.circle.fill")
                .font(.system(size: 18, weight: .bold))
                .foregroundStyle(Theme.successText)
            Text(message)
                .font(type.bodyStrong)
                .foregroundStyle(Theme.textPrimary)
            Spacer()
        }
        .padding(16)
        .background(
            RoundedRectangle(cornerRadius: Theme.Radius.lg, style: .continuous)
                .fill(Theme.successSoft)
        )
        .overlay(
            RoundedRectangle(cornerRadius: Theme.Radius.lg, style: .continuous)
                .strokeBorder(Theme.successText.opacity(0.4), lineWidth: 1)
        )
        .transition(.move(edge: .top).combined(with: .opacity))
    }

    // MARK: - Bottom Bar

    private var bottomBar: some View {
        VStack(spacing: 8) {
            Button("Done") {
                dismiss()
            }
            .buttonStyle(DashboardButtonStyle(kind: .primary))
        }
        .padding(.horizontal, 20)
        .padding(.vertical, 12)
        .background(Theme.glassSheet)
    }
}

